async function costSummary(db) {
  const row=await db.prepare("SELECT (SELECT COUNT(*) FROM api_usage) AS request_count, (SELECT COUNT(*) FROM command_runs) AS instruction_count, (SELECT COALESCE(SUM(cost_usd), 0) FROM api_usage) AS cumulative_usd").first();
  const requests=Number(row?.request_count||0), instructions=Number(row?.instruction_count||0), cumulative=Number(row?.cumulative_usd||0);
  return {request_count:requests,instruction_count:instructions,cumulative_usd:cumulative,average_per_instruction_usd:instructions?cumulative/instructions:0};
}
async function recentCost(db) {
  return db.prepare("SELECT cost_usd, input_tokens, output_tokens, created_at FROM api_usage ORDER BY id DESC LIMIT 1").first();
}
async function saveRun(db, runId, events, elapsedMs) {
  const decisions=events.filter(e=>e.kind==='decision'&&!e.status), terminal=[...events].reverse().find(e=>e.kind==='result'||e.kind==='error');
  const stored=events.filter(e=>e.kind!=='debug');
  const cost=decisions.reduce((sum,e)=>sum+Number(e.costs?.request_usd||0),0);
  await db.prepare("UPDATE command_runs SET status = ?, intent = ?, target = ?, cost_usd = ?, elapsed_ms = ?, events_json = ? WHERE id = ?")
    .bind(terminal?.status||'error',decisions.find(e=>e.stage===1)?.intent||null,decisions.find(e=>e.stage===2)?.device||null,cost,elapsedMs,JSON.stringify(stored),runId).run();
}
async function history(db,clientId) {
  const result=await db.prepare("SELECT id, created_at, input_text, status, intent, target, cost_usd, elapsed_ms, events_json FROM command_runs WHERE client_id = ? ORDER BY created_at DESC LIMIT 20").bind(clientId).all();
  return (result.results||[]).map(({events_json,...row})=>({...row,events:JSON.parse(events_json||'[]')}));
}

function json(data, status=200) { return new Response(JSON.stringify(data), {status, headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}}); }
function ndjson(events) { return new Response(events.map(e=>JSON.stringify(e)).join("\n")+"\n", {headers:{"content-type":"application/x-ndjson; charset=utf-8","cache-control":"no-store"}}); }
function decode(b64) { return Uint8Array.from(atob(b64), c=>c.charCodeAt(0)); }
function initial(data) { return Object.fromEntries(data.devices.map(d=>[d.id,Object.fromEntries(d.capabilities.map(c=>[c.key,c.value]))])); }
function choice(instructions, criteria) { return {type:"choice", instructions, criteria}; }
async function ask(env, state, questions, runId) {
  const start=Date.now();
  const response=await fetch("https://api.typesafe.ai/v1/systemone", {method:"POST",headers:{authorization:`Bearer ${env.JEV_API_KEY}`,"content-type":"application/json",accept:"application/json"},body:JSON.stringify({state,model:"jev-latest",questions})});
  if(!response.ok) throw new Error(`Jev HTTP ${response.status}: ${(await response.text()).slice(0,500)}`);
  const data=await response.json();
  const usage=data.usage||{}, input=Number(usage.input_tokens||0), output=Number(usage.output_tokens||0), cost=input*PRICE/1e6;
  await env.DB.prepare("INSERT INTO api_usage (run_id, created_at, input_tokens, output_tokens, cost_usd) VALUES (?, ?, ?, ?, ?)")
    .bind(runId,new Date().toISOString(),input,output,cost).run();
  const summary=await costSummary(env.DB);
  return {data,ms:Date.now()-start,costs:{request_usd:cost,instruction_usd:cost,input_tokens:input,output_tokens:output,...summary,input_price_per_million_usd:PRICE,pricing_basis:"public_input_token_rate"}};
}
const INTENTS={home_query:"查询智能家居设备、状态、当前数值或设备清单，不改变状态",home_control:"立即控制智能家居设备",ai_question:"向豆包大模型咨询知识或闲聊",scheduled_control:"稍后或周期性控制智能家居",music:"搜索或播放音乐、歌曲或歌手",unclear:"无关、信息不足或无法归类"};
