  const rooms=data.rooms.map(r=>r.name), explicit=rooms.find(n=>text.includes(n)), roomAliases=[["我的卧室","主卧"],["卧室","主卧"],["大厅","客厅"]], alias=roomAliases.find(([a])=>text.includes(a))?.[1], room=explicit||alias||(rooms.includes(body.room)?body.room:null), type=body.device_type;
